import numpy as np
seq = ""
arr = np.array(list(seq))
print(arr[0:50])
window = arr[0:50]
gc_mask = (window == "G") | (window == "C")
print(gc_mask)
gc = gc_mask.sum() / len(window) * 100
window2 = arr[50:100]
gc2 = ((window2 == "G") | (window2 == "C")).sum() / len(window2) * 100
print(f"window 1(base 1 - 50): {gc:.2f}%")
print(f"window 2(base 50 - 100): {gc2:.2f}%")
